import Foundation
import XCTest
@testable import ColorComposerCore

/// Replays the committed v1 corpus generated by `color_matching`.
///
/// The fixture is copied verbatim from
/// `viamin/color_matching/priv/parity/v1/corpus.json`. Keep this test focused
/// on the public scorer and solver contracts so a future generated client or
/// internal fast-path optimization cannot mask a semantic drift.
final class WeightedSquaredErrorParityTests: XCTestCase {
    func testV1CorpusMatchesScoresAndSelectionsExactly() throws {
        let corpus = try loadCorpus()
        XCTAssertEqual(corpus.algorithmVersion, 1)
        XCTAssertEqual(corpus.scorer, "ColorMatching.WeightedSquaredError")
        XCTAssertEqual(corpus.selection, "earliest-index-wins")

        let scorer = WeightedSquaredErrorScorer()
        for scenario in corpus.scenarios {
            let palette = scenario.palette.map(makeColor)
            let target = TargetResponseVector(channels: scenario.target.channels)
            let weights = ChannelWeights(channels: scenario.weights)

            for expectedScore in scenario.expected.scores {
                let result = scorer.score(
                    candidate: palette[expectedScore.index], target: target, weights: weights
                )
                switch (result, expectedScore.score) {
                case (.excluded, .excluded):
                    break
                case (.score(let actual), .value(let expected)):
                    XCTAssertEqual(actual, expected, accuracy: 0, "scenario: \(scenario.id), index: \(expectedScore.index)")
                default:
                    XCTFail("score mismatch for scenario: \(scenario.id), index: \(expectedScore.index)")
                }
            }

            // The solver always builds a complete target from its active source
            // grids. For the corpus's missing-target scenario, scorer results
            // above are the applicable contract; the selection is necessarily
            // absent before the solver can be called.
            if weights.activeConditions.allSatisfy({ target.value(for: $0) != nil }) {
                let result = try CompositionSolver().solve(
                    palette: palette,
                    sourceGrids: sourceGrids(for: target, weights: weights),
                    weights: weights
                )
                let selectedIndex = result.colorIndex(x: 0, y: 0)
                XCTAssertEqual(selectedIndex, scenario.expected.selectedIndex, "scenario: \(scenario.id)")
                XCTAssertEqual(
                    selectedIndex.map { palette[$0].hex }, scenario.expected.selectedHexColor,
                    "scenario: \(scenario.id)"
                )

                if let expectedError = scenario.expected.error {
                    XCTAssertEqual(result.error(x: 0, y: 0), expectedError, accuracy: 0, "scenario: \(scenario.id)")
                } else {
                    XCTAssertTrue(result.error(x: 0, y: 0).isInfinite, "scenario: \(scenario.id)")
                }

                if scenario.expected.tieBroke == true {
                    let selected = try XCTUnwrap(selectedIndex, "scenario: \(scenario.id)")
                    XCTAssertEqual(selected, scenario.expected.tiedIndices.min(), "scenario: \(scenario.id)")
                }
            }
        }
    }

    private func loadCorpus() throws -> ParityCorpus {
        let testDirectory = URL(fileURLWithPath: #filePath).deletingLastPathComponent()
        let fixtureURL = testDirectory
            .appendingPathComponent("Fixtures", isDirectory: true)
            .appendingPathComponent("weighted_squared_error_v1.json")
        return try JSONDecoder().decode(ParityCorpus.self, from: Data(contentsOf: fixtureURL))
    }

    private func makeColor(_ candidate: ParityCandidate) -> PaletteColor {
        let responses = candidate.channels.reduce(into: [LightingCondition: IlluminationResponse]()) {
            partialResult, entry in
            guard let condition = LightingCondition(rawValue: entry.key) else { return }
            partialResult[condition] = IlluminationResponse(brightness: entry.value)
        }
        return PaletteColor(
            id: candidate.index!,
            hex: candidate.hexColor,
            rgb: RGBColor(hex: candidate.hexColor)!,
            responses: responses
        )
    }

    private func sourceGrids(
        for target: TargetResponseVector,
        weights: ChannelWeights
    ) -> [LightingCondition: BrightnessGrid] {
        Dictionary(uniqueKeysWithValues: weights.activeConditions.map {
            ($0, BrightnessGrid(width: 1, height: 1, values: [target.value(for: $0) ?? 0]))
        })
    }
}

private struct ParityCorpus: Decodable {
    let algorithmVersion: Int
    let scorer: String
    let selection: String
    let scenarios: [ParityScenario]
}

private struct ParityScenario: Decodable {
    let id: String
    let palette: [ParityCandidate]
    let target: ParityCandidate
    let weights: [String: Double]
    let expected: ParityExpected
}

private struct ParityCandidate: Decodable {
    let channels: [String: Double]
    let hexColor: String
    let index: Int?
}

private struct ParityExpected: Decodable {
    let error: Double?
    let scores: [ParityScore]
    let selectedHexColor: String?
    let selectedIndex: Int?
    let tieBroke: Bool?
    let tiedIndices: [Int]
}

private struct ParityScore: Decodable {
    let index: Int
    let score: ParityScoreValue
}

private enum ParityScoreValue: Decodable {
    case value(Double)
    case excluded

    init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let value = try? container.decode(Double.self) {
            self = .value(value)
        } else if try container.decode(String.self) == "excluded" {
            self = .excluded
        } else {
            throw DecodingError.dataCorruptedError(in: container, debugDescription: "Expected a score or excluded")
        }
    }
}

private extension TargetResponseVector {
    init(channels: [String: Double]) {
        self.init(channels.reduce(into: [LightingCondition: Double]()) { partialResult, entry in
            guard let condition = LightingCondition(rawValue: entry.key) else { return }
            partialResult[condition] = entry.value
        })
    }
}

private extension ChannelWeights {
    init(channels: [String: Double]) {
        self.init(
            white: channels["white"] ?? 0,
            red: channels["red"] ?? 0,
            green: channels["green"] ?? 0,
            blue: channels["blue"] ?? 0,
            lps: channels["lps"] ?? 0
        )
    }
}
